// 5.2 — новое входящее SMS на номер компании (создание работы из свежего сообщения): автоматизировать нельзя — SMS шлёт человек; skip.
// Источник: «מה רצוי» тикета — Country заполняется, когда адрес распознан; ZIP из сообщения сохраняется как есть.
// Не сверено с сайтом при записи: подписи полей формы работы («Country», «ZIP Code» — по скриншоту 621cd7-A-job0020-zip-country-desktop.png),
// строка клиента на /customers (поиск по имени).
import { test, expect } from '../../fixtures';
import { ROLE, prepare, openGpsAll, openMessage, openJobFromDialog } from './gps-helpers';

const CLIENT = 'QA-Gil Shore';

test.describe('GPS Workflow — Country and ZIP in a job created from SMS (#621cd7)', () => {
  test('Existing job from the "FL 33132" message: Country United States, ZIP 33132 in the job and in the client #621cd7 @desktop @prod-safe', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    await prepare(page);
    await openGpsAll(page);
    const dialog = await openMessage(page, new RegExp(`^${CLIENT}\\b`));
    await openJobFromDialog(page, dialog);

    await expect(page.getByLabel('Country')).toHaveValue(/United States|USA/, { timeout: 30_000 });
    await expect(page.getByLabel('ZIP Code')).toHaveValue('33132');
    await expect(page.getByRole('textbox', { name: /^Address/ })).toHaveValue(/FL 33132/);

    // Клиент созданный из того же сообщения — тот же ZIP
    await page.goto('/customers');
    await page.getByPlaceholder(/^Search/i).first().fill(CLIENT);
    await page.getByText(CLIENT, { exact: true }).filter({ visible: true }).first().click();
    await page.waitForURL(/\/CustomerDetail/i, { timeout: 30_000 });
    await expect(page.locator('main')).toContainText('33132', { timeout: 20_000 });
    await expect(page.locator('main')).not.toContainText('33131');
  });

  test.describe('new incoming SMS', () => {
    test.skip(true, 'нужен входящий SMS на номер компании (+1 (507) 568-6036) с адресом «…Miami, FL 33132» — отправляет человек');
    test('New SMS "…Miami, FL 33132" → Create job: Country filled, ZIP 33132 kept in the job and the client; street and city unchanged (#324ddc) #621cd7 @desktop @writes', async () => {
      // 1. Отправить SMS шаблона Name/Phone/Desc/Address на номер компании. 2. GPS Workflow → New → Create job → Open job.
      // 3. Country = United States, ZIP = 33132 (поле и строка адреса), улица и город — как в сообщении.
    });
  });
});
